INIT_BLOCK = '\nfrom .oracle_certified_research_evidence_collection_batch_manifest_builder import (\n    EVIDENCE_BATCH_ENTRY_AUTHORIZED,\n    EVIDENCE_BATCH_ISSUED,\n    EVIDENCE_BATCH_POLICY_ID,\n    OracleCertifiedResearchEvidenceCollectionBatchEntry,\n    OracleCertifiedResearchEvidenceCollectionBatchManifest,\n    OracleCertifiedResearchEvidenceCollectionBatchManifestBuilder,\n)\n\n__all__ = [\n    "EVIDENCE_BATCH_ENTRY_AUTHORIZED",\n    "EVIDENCE_BATCH_ISSUED",\n    "EVIDENCE_BATCH_POLICY_ID",\n    "OracleCertifiedResearchEvidenceCollectionBatchEntry",\n    "OracleCertifiedResearchEvidenceCollectionBatchManifest",\n    "OracleCertifiedResearchEvidenceCollectionBatchManifestBuilder",\n] + __all__\n'

def verify_oia027() -> None:
    if not OIA027.exists():
        raise RuntimeError(f"Actual OIA-027 production module missing: {OIA027}")
    source = OIA027.read_text(encoding="utf-8")
    required = [
        'SCHEMA_VERSION = "OIA-027"', 'ENGINE_ID = "OIA-027"', 'EVIDENCE_SESSION_POLICY_ID',
        'EVIDENCE_SESSION_ACTIVE', 'EVIDENCE_ENTRY_ACTIVE', 'source_evidence_manifest_hash',
        'source_certification_hash', 'source_readiness_hash', 'source_session_hash', 'source_activation_hash',
        'source_claim_hash', 'source_dispatch_manifest_hash', 'source_batch_hash', 'session_entry_hash',
        'authorized_evidence_operations', 'prohibited_operations', 'read_only_corpus', 'evidence_collection_allowed',
        'research_execution_allowed', 'analytic_conclusion_allowed', 'forecast_creation_allowed',
        'qseries_handoff_allowed', 'market_order_creation_allowed', 'funds_movement_allowed', 'portfolio_mutation_allowed',
    ]
    missing = [token for token in required if token not in source]
    if missing:
        raise RuntimeError(f"Actual OIA-027 production contract mismatch: {missing}")

def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.rstrip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")

def update_init() -> None:
    source = INIT.read_text(encoding="utf-8") if INIT.exists() else "__all__ = []\n"
    marker = "from .oracle_certified_research_evidence_collection_batch_manifest_builder import ("
    if marker not in source:
        source = source.rstrip() + "\n" + INIT_BLOCK
        INIT.write_text(source.rstrip() + "\n", encoding="utf-8")
        print(f"[OK] PACKAGE UPDATED: {INIT}")
    else:
        print(f"[OK] PACKAGE ALREADY CURRENT: {INIT}")

def main() -> int:
    print("=" * 40)
    print(" OIA-028 INSTALLER")
    print(" CERTIFIED EVIDENCE COLLECTION BATCH")
    print(" READ-ONLY MANIFEST BUILDER")
    print("=" * 40)
    verify_oia027()
    print("[OK] Actual OIA-027 evidence session contract verified")
    write_full_replacement(PRODUCTION, PRODUCTION_SOURCE)
    write_full_replacement(TEST, TEST_SOURCE)
    update_init()
    py_compile.compile(str(PRODUCTION), doraise=True)
    py_compile.compile(str(TEST), doraise=True)
    py_compile.compile(str(INIT), doraise=True)
    print("[OK] Production, test, and package syntax verified")
    result = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if result.returncode != 0:
        raise SystemExit(result.returncode)
    print("[OK] OIA-028 test executed automatically")
    print()
    print("[DONE] OIA-028 certified research evidence collection batch manifest builder installed")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
